import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { BRAND } from "@/lib/brand";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
  inOutEnvelope,
} from "../motion";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 15;

// Three made-up channels, each with subs ~500k and a views→subs ratio that triples.
type Channel = {
  handle: string;
  name: string;
  avatarHue: number; // for the colored avatar bubble
  subs: number;
  ratioStart: number; // views per subscriber, "before"
  ratioEnd: number; // views per subscriber, "after" (~3x)
};

const CHANNELS: Channel[] = [
  {
    handle: "@northpinestudio",
    name: "North Pine Studio",
    avatarHue: 18,
    subs: 482_300,
    ratioStart: 1.4,
    ratioEnd: 4.3,
  },
  {
    handle: "@quietframe",
    name: "Quiet Frame",
    avatarHue: 32,
    subs: 517_900,
    ratioStart: 2.1,
    ratioEnd: 6.4,
  },
  {
    handle: "@dailybyteclub",
    name: "Daily Byte Club",
    avatarHue: 12,
    subs: 534_650,
    ratioStart: 1.7,
    ratioEnd: 5.2,
  },
];

const Background: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }}>
    <Img
      src={staticFile("assets/backgrounds/background.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover", opacity: 0.85 }}
    />
    {/* warm low-glow from bottom-left */}
    <div
      style={{
        position: "absolute",
        left: "-10%",
        bottom: "-15%",
        width: "70%",
        height: "70%",
        background: `radial-gradient(closest-side, ${COLORS.orange}, transparent)`,
        opacity: 0.08,
        filter: "blur(40px)",
        mixBlendMode: "screen",
      }}
    />
  </AbsoluteFill>
);

// ---------- SCENE 1: INTRO ----------

const sceneIntroDuration = 110;

const SceneIntro: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const eyebrowIn = springIn(frame, fps, 4, "GENTLE");
  const titleIn = springIn(frame, fps, 10, "SNAPPY");
  const highlightReveal = springIn(frame, fps, 26, "LIQUID");
  const subIn = springIn(frame, fps, 38, "GENTLE");

  const driftY = ambientDrift(frame, 3, 110, "intro-title");
  const eyebrowDrift = ambientDrift(frame, 1.5, 90, "intro-eyebrow");

  const envelope = inOutEnvelope(frame, fps, sceneIntroDuration);

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif", opacity: envelope }}>
      <Background />

      {/* off-center anchored composition */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "22%",
          maxWidth: "78%",
        }}
      >
        {/* eyebrow */}
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontSize: 44,
            fontWeight: 500,
            letterSpacing: "0.22em",
            textTransform: "uppercase",
            color: COLORS.textSubtle,
            opacity: eyebrowIn,
            transform: `translateY(${interpolate(eyebrowIn, [0, 1], [14, eyebrowDrift])}px)`,
            marginBottom: 56,
          }}
        >
          Case study · 3 channels
        </div>

        {/* headline */}
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: 268,
            lineHeight: 1.02,
            letterSpacing: "-0.035em",
            color: COLORS.text,
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [40, driftY])}px) scale(${interpolate(
              titleIn,
              [0, 1],
              [0.94, 1],
            )})`,
            filter: `blur(${interpolate(titleIn, [0, 1], [10, 0])}px)`,
          }}
        >
          They{" "}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `8px solid ${COLORS.orange}`,
              padding: "0 26px",
              borderRadius: 18,
              color: COLORS.text,
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              clipPath: `inset(0 ${interpolate(highlightReveal, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            tripled
          </span>
          <br />
          their views-to-subs ratio.
        </div>

        {/* subhead */}
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontSize: 52,
            fontWeight: 500,
            lineHeight: 1.35,
            color: COLORS.textMuted,
            marginTop: 80,
            maxWidth: "60%",
            opacity: subIn,
            transform: `translateY(${interpolate(subIn, [0, 1], [16, 0])}px)`,
          }}
        >
          Same ~500k subscribers. 3× the reach per subscriber.
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ---------- SCENE 2: THREE CHANNEL CARDS ----------

const sceneChannelsDuration = 360;

// Format big numbers as e.g. "1.34M" or "523,400"
const formatNumber = (n: number): string => {
  if (n >= 1_000_000) {
    return `${(n / 1_000_000).toFixed(2)}M`;
  }
  if (n >= 10_000) {
    return Math.round(n).toLocaleString("en-US");
  }
  return Math.round(n).toLocaleString("en-US");
};

const ArrowUpIcon: React.FC<{ size: number; color: string; progress: number }> = ({
  size,
  color,
  progress,
}) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ opacity: progress }}>
    <path
      d="M12 19 L12 5 M5 12 L12 5 L19 12"
      stroke={color}
      strokeWidth={2.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
      strokeDasharray={40}
      strokeDashoffset={interpolate(progress, [0, 1], [40, 0])}
    />
  </svg>
);

type CardProps = {
  channel: Channel;
  index: number;
  baseDelay: number;
};

const ChannelCard: React.FC<CardProps> = ({ channel, index, baseDelay }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // entrance
  const cardIn = staggeredSpring(
    frame,
    fps,
    index,
    baseDelay,
    TIMING.staggerItem + 4,
    "LIQUID",
  );

  // ratio animation phases (relative to frame)
  // The "before" ratio holds, then counts up to the "after" value.
  const localFrame = frame - (baseDelay + index * (TIMING.staggerItem + 4) + 20);
  const beforeHold = interpolate(localFrame, [0, 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const rampProgress = spring({
    frame: localFrame,
    fps,
    delay: 50,
    config: SPRINGS.LIQUID,
  });

  const currentRatio = interpolate(
    rampProgress,
    [0, 1],
    [channel.ratioStart, channel.ratioEnd],
  );
  const currentViews = channel.subs * currentRatio;

  // multiplier badge appears after the ramp completes
  const badgeIn = spring({
    frame: localFrame,
    fps,
    delay: 70,
    config: SPRINGS.ELASTIC,
  });

  // bar fill widths (relative within the card)
  const subsBarFill = spring({
    frame: localFrame,
    fps,
    delay: 6,
    config: SPRINGS.LIQUID,
  });
  // views bar tracks the current ratio against the max ratio across all channels
  const maxRatio = Math.max(...CHANNELS.map((c) => c.ratioEnd));
  const viewsBarTarget = currentRatio / maxRatio;

  const ambDriftY = ambientDrift(frame, 2, 95, `card-${index}`);

  const tx = interpolate(cardIn, [0, 1], [60, 0]);
  const sc = interpolate(cardIn, [0, 1], [0.94, 1]);
  const bl = interpolate(cardIn, [0, 1], [10, 0]);

  return (
    <div
      style={{
        background: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 28,
        padding: "56px 60px",
        display: "flex",
        flexDirection: "column",
        gap: 36,
        opacity: cardIn,
        transform: `translateY(${tx + ambDriftY}px) scale(${sc})`,
        filter: `blur(${bl}px)`,
      }}
    >
      {/* channel identity row */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 28,
          fontFamily: "Inter, sans-serif",
        }}
      >
        {/* avatar bubble */}
        <div
          style={{
            width: 92,
            height: 92,
            borderRadius: "50%",
            background: `linear-gradient(135deg, hsl(${channel.avatarHue}, 88%, 56%), hsl(${
              channel.avatarHue + 12
            }, 92%, 48%))`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            color: "#fff",
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: 44,
            letterSpacing: "-0.02em",
            flexShrink: 0,
            boxShadow: `0 8px 32px hsla(${channel.avatarHue}, 88%, 50%, 0.25)`,
          }}
        >
          {channel.name.charAt(0)}
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 4, flex: 1 }}>
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontWeight: 600,
              fontSize: 42,
              color: COLORS.text,
              letterSpacing: "-0.015em",
              lineHeight: 1.1,
            }}
          >
            {channel.name}
          </div>
          <div
            style={{
              fontFamily: "Inter, sans-serif",
              fontSize: 28,
              fontWeight: 500,
              color: COLORS.textSubtle,
              letterSpacing: "0.005em",
            }}
          >
            {channel.handle}
          </div>
        </div>

        {/* 3× badge */}
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: 56,
            color: COLORS.orange,
            background: COLORS.orangeTint,
            border: `2px solid ${COLORS.orange}`,
            borderRadius: 18,
            padding: "10px 28px",
            letterSpacing: "-0.02em",
            display: "flex",
            alignItems: "center",
            gap: 12,
            opacity: badgeIn,
            transform: `scale(${interpolate(badgeIn, [0, 1], [0.6, 1])})`,
          }}
        >
          <ArrowUpIcon size={42} color={COLORS.orange} progress={badgeIn} />
          3×
        </div>
      </div>

      {/* subscribers row */}
      <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "baseline",
            fontFamily: "Inter, sans-serif",
          }}
        >
          <div
            style={{
              fontSize: 30,
              fontWeight: 500,
              color: COLORS.textSubtle,
              letterSpacing: "0.14em",
              textTransform: "uppercase",
            }}
          >
            Subscribers
          </div>
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontSize: 56,
              fontWeight: 700,
              color: COLORS.text,
              letterSpacing: "-0.02em",
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {formatNumber(channel.subs)}
          </div>
        </div>
        {/* track */}
        <div
          style={{
            height: 18,
            background: "rgba(255,255,255,0.06)",
            borderRadius: 9,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              width: `${subsBarFill * 38}%`,
              height: "100%",
              background: COLORS.textMuted,
              borderRadius: 9,
            }}
          />
        </div>
      </div>

      {/* monthly views row */}
      <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "baseline",
            fontFamily: "Inter, sans-serif",
          }}
        >
          <div
            style={{
              fontSize: 30,
              fontWeight: 500,
              color: COLORS.orange,
              letterSpacing: "0.14em",
              textTransform: "uppercase",
            }}
          >
            Monthly views
          </div>
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontSize: 64,
              fontWeight: 800,
              color: COLORS.text,
              letterSpacing: "-0.025em",
              fontVariantNumeric: "tabular-nums",
              display: "flex",
              alignItems: "baseline",
              gap: 14,
            }}
          >
            {formatNumber(currentViews)}
          </div>
        </div>
        {/* track */}
        <div
          style={{
            height: 18,
            background: "rgba(255,255,255,0.06)",
            borderRadius: 9,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              width: `${viewsBarTarget * 100 * beforeHold}%`,
              height: "100%",
              background: `linear-gradient(90deg, ${COLORS.orange}, ${COLORS.orangeDeep})`,
              borderRadius: 9,
              boxShadow: `0 0 24px ${COLORS.orange}44`,
            }}
          />
        </div>

        {/* ratio caption */}
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontSize: 26,
            fontWeight: 500,
            color: COLORS.textMuted,
            marginTop: 6,
            display: "flex",
            alignItems: "center",
            gap: 14,
            fontVariantNumeric: "tabular-nums",
          }}
        >
          <span style={{ color: COLORS.textSubtle }}>views / sub</span>
          <span
            style={{
              color: COLORS.text,
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontWeight: 700,
              fontSize: 32,
            }}
          >
            {currentRatio.toFixed(2)}
          </span>
          <span style={{ color: COLORS.textSubtle }}>·</span>
          <span style={{ color: COLORS.textSubtle, textDecoration: "line-through" }}>
            was {channel.ratioStart.toFixed(2)}
          </span>
        </div>
      </div>
    </div>
  );
};

const SceneChannels: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const titleIn = springIn(frame, fps, 4, "SNAPPY");
  const highlightIn = springIn(frame, fps, 16, "LIQUID");
  const subIn = springIn(frame, fps, 24, "GENTLE");

  const titleDrift = ambientDrift(frame, 2, 120, "channels-title");

  const envelope = inOutEnvelope(frame, fps, sceneChannelsDuration);

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif", opacity: envelope }}>
      <Background />

      {/* asymmetric grid: header on the left band, cards in the wider right band */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "grid",
          gridTemplateColumns: "1fr 1.55fr",
          gap: 140,
          padding: "9% 8%",
          alignItems: "stretch",
        }}
      >
        {/* LEFT: headline column */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            gap: 56,
            paddingTop: 80,
          }}
        >
          <div
            style={{
              fontFamily: "Inter, sans-serif",
              fontSize: 38,
              fontWeight: 500,
              letterSpacing: "0.2em",
              textTransform: "uppercase",
              color: COLORS.textSubtle,
              opacity: titleIn,
              transform: `translateY(${interpolate(titleIn, [0, 1], [14, 0])}px)`,
            }}
          >
            The shift
          </div>
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontWeight: 700,
              fontSize: 132,
              lineHeight: 1.02,
              letterSpacing: "-0.035em",
              color: COLORS.text,
              opacity: titleIn,
              transform: `translateY(${interpolate(titleIn, [0, 1], [28, titleDrift])}px)`,
              filter: `blur(${interpolate(titleIn, [0, 1], [8, 0])}px)`,
            }}
          >
            Same audience.{" "}
            <span
              style={{
                background: COLORS.orangeTint,
                borderBottom: `6px solid ${COLORS.orange}`,
                padding: "0 18px",
                borderRadius: 12,
                clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
              }}
            >
              Triple
            </span>{" "}
            the reach.
          </div>
          <div
            style={{
              fontFamily: "Inter, sans-serif",
              fontSize: 38,
              fontWeight: 500,
              lineHeight: 1.4,
              color: COLORS.textMuted,
              maxWidth: 640,
              opacity: subIn,
              transform: `translateY(${interpolate(subIn, [0, 1], [14, 0])}px)`,
            }}
          >
            Watch monthly views climb against a flat subscriber count — the views-per-subscriber
            ratio jumps roughly 3×.
          </div>
        </div>

        {/* RIGHT: three channel cards stacked */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 44,
            justifyContent: "center",
          }}
        >
          {CHANNELS.map((c, i) => (
            <ChannelCard key={c.handle} channel={c} index={i} baseDelay={36} />
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ---------- SCENE 3: SUMMARY ----------

const sceneSummaryDuration = 150;

const SceneSummary: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const eyebrowIn = springIn(frame, fps, 4, "GENTLE");
  const numberIn = spring({ frame, fps, delay: 10, config: SPRINGS.LIQUID });
  const labelIn = springIn(frame, fps, 30, "SNAPPY");
  const captionIn = springIn(frame, fps, 46, "GENTLE");

  const driftY = ambientDrift(frame, 2.5, 100, "summary-hero");
  const driftLabel = ambientDrift(frame, 1.5, 130, "summary-label");

  const counter = interpolate(numberIn, [0, 1], [0, 3]);

  const envelope = inOutEnvelope(frame, fps, sceneSummaryDuration);

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif", opacity: envelope }}>
      <Background />

      {/* off-center hero — anchored slightly left & low */}
      <div
        style={{
          position: "absolute",
          left: "10%",
          top: "26%",
          maxWidth: "82%",
        }}
      >
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontSize: 42,
            fontWeight: 500,
            letterSpacing: "0.22em",
            textTransform: "uppercase",
            color: COLORS.textSubtle,
            opacity: eyebrowIn,
            transform: `translateY(${interpolate(eyebrowIn, [0, 1], [12, 0])}px)`,
            marginBottom: 28,
          }}
        >
          Across all three channels
        </div>

        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            gap: 56,
            transform: `translateY(${driftY}px)`,
          }}
        >
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontWeight: 800,
              fontSize: 740,
              lineHeight: 0.85,
              letterSpacing: "-0.05em",
              color: COLORS.text,
              fontVariantNumeric: "tabular-nums",
              opacity: numberIn,
              transform: `scale(${interpolate(numberIn, [0, 1], [0.86, 1])})`,
              filter: `blur(${interpolate(numberIn, [0, 1], [14, 0])}px)`,
              textShadow: `0 8px 80px ${COLORS.orange}33`,
            }}
          >
            {counter.toFixed(1)}
            <span
              style={{
                fontFamily: "'GT Walsheim', Inter, sans-serif",
                color: COLORS.orange,
                background: COLORS.orangeTint,
                borderBottom: `12px solid ${COLORS.orange}`,
                padding: "0 36px",
                borderRadius: 24,
                fontSize: 460,
                marginLeft: 36,
                opacity: interpolate(numberIn, [0.7, 1], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }),
              }}
            >
              ×
            </span>
          </div>
        </div>

        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 600,
            fontSize: 96,
            color: COLORS.text,
            letterSpacing: "-0.025em",
            lineHeight: 1.05,
            marginTop: 56,
            opacity: labelIn,
            transform: `translateY(${interpolate(labelIn, [0, 1], [20, driftLabel])}px)`,
          }}
        >
          views per subscriber
        </div>

        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontSize: 42,
            fontWeight: 500,
            color: COLORS.textMuted,
            marginTop: 36,
            maxWidth: 1400,
            lineHeight: 1.35,
            opacity: captionIn,
            transform: `translateY(${interpolate(captionIn, [0, 1], [14, 0])}px)`,
          }}
        >
          Same subscriber base. Three times the monthly reach.
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ---------- MAIN COMPOSITION ----------

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={sceneIntroDuration + TRANSITION}>
        <SceneIntro />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={sceneChannelsDuration + TRANSITION}>
        <SceneChannels />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={sceneSummaryDuration}>
        <SceneSummary />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export const durationInFrames =
  sceneIntroDuration + sceneChannelsDuration + sceneSummaryDuration + TRANSITION;

export default MainComposition;
